rcore 1; package paint version "1";
metamodel "urn:inferred:paint" prefix p {
 datatype RGB instanceClass "example.RGB" {}
 class Paint { attr color: RGB [0,1] default "#123abc"; }
}

grammar contexts.rgb.Language hidden(WS)
generate model "urn:contexts:rgb"
import "urn:inferred:paint" as p
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model: child=Paint<false>;
Paint<Flag> returns p::Paint: {p::Paint} (<Flag> 'yes' | <!Flag> 'paint');
terminal WS: (' '|'\t'|'\r'|'\n')+;
terminal ANY_OTHER: .;

